	 * Signs the data passed in ARG4.  The ARG3 can be sha1, sha256, sha384, sha512, or none.  If not equal to none, then the hash of the data passed in ARG4 is signed.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkScMinidriverRef.html#SignData
	 * @param int $containerIndex
	 * @param ?string $keySpec
	 * @param ?string $hashDataAlg
	 * @param CkBinData $bdData
	 * @param CkBinData $bdSignedData
	 * @return bool
	 */
	function SignData($containerIndex,$keySpec,$hashDataAlg,$bdData,$bdSignedData) {
		return CkScMinidriver_SignData($this->_cPtr,$containerIndex,$keySpec,$hashDataAlg,$bdData,$bdSignedData);
	}

	/**
	 * Writes the entire file specified by ARG1 and ARG2.   ARG1 is the name of the directory that contains the file, or the empty string for root.  The entire contents of ARG3 are written to the file on the smart card.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkScMinidriverRef.html#WriteFile
	 * @param ?string $dirName
	 * @param ?string $fileName
	 * @param CkBinData $bd
	 * @return bool
	 */
	function WriteFile($dirName,$fileName,$bd) {
		return CkScMinidriver_WriteFile($this->_cPtr,$dirName,$fileName,$bd);
	}
}
